referenceSolutionTemplate:
#include <stdio.h>
#include <stdarg.h>

void report(const char *fmt, ...) {
    va_list list;
    va_start(list, fmt);
    vprintf(fmt, list);
    va_end(list);
    printf("\n");
}

int main(void) {
    report("{msg}：%d 条", {a});
    report("今天到此为止");
    return 0;
}
